referenceSolutions.javascript:
function ribbonRunsEvenKeyCensus(line, k) {
  const a=line; let out=[];
  for(let i=0;i<a.length;){let j=i+1;while(j<a.length&&a[j]===a[i])j++;out.push(j-i);i=j;}
  return out.filter(x=>x%2===0).length;
}

